fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    let len = m.max(n);

    // If `a` already has the target length, just reuse it.
    // Otherwise it must be length 1 (by assumption) so we repeat its single value.
    let out_a = if m == len {
        a
    } else {
        vec![a[0]; len]
    };

    // Same logic for `b`.
    let out_b = if n == len {
        b
    } else {
        vec![b[0]; len]
    };

    (out_a, out_b)
}

